#include "robotblocks_runtime.h"

struct RbMotor { int pwm = -1, ina = -1, inb = -1; };
static RbMotor motores_puente[4];
inline int motores_indice(const String& motor);
inline int motores_indice(const String& motor) { return motor.length() == 1 ? motor[0] - 'A' : -1; }
inline void motores_configurar(const String& motor, int pwm, int ina, int inb);
inline void motores_configurar(const String& motor, int pwm, int ina, int inb) {
    int i = motores_indice(motor); if (i < 0 || i > 3) return;
    motores_puente[i].pwm = pwm; motores_puente[i].ina = ina; motores_puente[i].inb = inb;
    pinMode(pwm, OUTPUT); pinMode(ina, OUTPUT); pinMode(inb, OUTPUT);
    digitalWrite(ina, LOW); digitalWrite(inb, LOW); analogWrite(pwm, 0);
}
inline void motores_parar(RbMotor& m, bool frenar);
inline void motores_parar(RbMotor& m, bool frenar) {
    digitalWrite(m.ina, frenar ? HIGH : LOW); digitalWrite(m.inb, frenar ? HIGH : LOW);
    analogWrite(m.pwm, frenar ? 255UL : 0);
}
inline void motores_velocidad(const String& motor, float velocidad, const char* bloque);
inline void motores_velocidad(const String& motor, float velocidad, const char* bloque) {
    int i = motores_indice(motor);
    if (i < 0 || i > 3 || motores_puente[i].pwm < 0) { rb_fail(bloque, RB_ERROR_TEXT("Motor sin configurar: usa configurar motor al iniciar")); return; }
    velocidad = fmaxf(-100, fminf(100, rb_finite(velocidad, bloque)));
    RbMotor& m = motores_puente[i];
    if (velocidad == 0) { motores_parar(m, false); return; }
    digitalWrite(m.ina, velocidad > 0 ? HIGH : LOW); digitalWrite(m.inb, velocidad > 0 ? LOW : HIGH);
    analogWrite(m.pwm, uint32_t(fabsf(velocidad) * 255UL / 100.0f));
}
inline void motores_detener(const String& motor, const String& modo);
inline void motores_detener(const String& motor, const String& modo) {
    for (int i = 0; i < 4; i++) if (motores_puente[i].pwm >= 0 && (motor == "todos" || motores_indice(motor) == i)) motores_parar(motores_puente[i], modo == "frenar");
}

static void proceso_1() {
    static RbProcessState s;
    PT_BEGIN(s);
    motores_configurar(String("B"), 5, 6, 7);
    if (rb_failed) return;
    motores_configurar(String("C"), 10, 11, 12);
    if (rb_failed) return;
    motores_velocidad(String("B"), 35, "aprende-492");
    motores_velocidad(String("C"), 35, "aprende-492");
    if (rb_failed) return;
    PT_SLEEP(s, 1000);
    motores_detener(String("todos"), String("frenar"));
    if (rb_failed) return;
    PT_SLEEP(s, 300);
    motores_velocidad(String("B"), 35, "aprende-500");
    motores_velocidad(String("C"), (-35), "aprende-500");
    if (rb_failed) return;
    PT_SLEEP(s, 400);
    motores_detener(String("todos"), String("frenar"));
    if (rb_failed) return;
    PT_END(s);
}

void setup() { Serial.begin(115200); }

void loop() { rb_error_repeat(); proceso_1(); }
